import { createContext, useContext, useEffect, useMemo, useState } from "react";
import api from "@/utils/api";

const AuthContext = createContext(null);
export const useAuth = () => useContext(AuthContext);

// --------- utils stockage ----------
const getToken = () =>
  localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");

const setAuthHeader = (token) => {
  if (token) api.defaults.headers.common["Authorization"] = `Bearer ${token}`;
  else delete api.defaults.headers.common["Authorization"];
};

const clearStorages = () => {
  localStorage.removeItem("adminToken");
  localStorage.removeItem("adminEmail");
  sessionStorage.removeItem("adminToken");
  sessionStorage.removeItem("adminEmail");
};

export function AuthProvider({ children }) {
  const [status, setStatus] = useState("checking"); // "checking" | "authenticated" | "unauthenticated"
  const [admin, setAdmin] = useState(null);

  // Normalise /admin/me (accepte {admin:{...}} ou l'objet plat)
  const normalizeMe = (data) => {
    if (!data) return null;
    if (data.admin && typeof data.admin === "object") return data.admin;
    return data; // {id,email,role}
  };

  const fetchMe = async () => {
    try {
      const { data } = await api.get("/admin/me");
      const me = normalizeMe(data);
      if (me && me.email) localStorage.setItem("adminEmail", me.email);
      setAdmin(me || null);
      setStatus("authenticated");
    } catch {
      clearStorages();
      setAuthHeader(null);
      setAdmin(null);
      setStatus("unauthenticated");
    }
  };

  // Au montage : si token → header + /admin/me, sinon non-auth
  useEffect(() => {
    const token = getToken();
    if (!token) {
      setStatus("unauthenticated");
      setAdmin(null);
      return;
    }
    setAuthHeader(token);
    fetchMe();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ——— actions exposées ———
  const login = async ({ token, admin: adminPayload, remember = true }) => {
    try {
      // stocker token
      if (remember) localStorage.setItem("adminToken", token);
      else sessionStorage.setItem("adminToken", token);

      // header axios
      setAuthHeader(token);

      // stocker email si présent
      const emailToKeep = adminPayload?.email;
      if (emailToKeep) {
        (remember ? localStorage : sessionStorage).setItem("adminEmail", emailToKeep);
      }

      // Si l’admin n’est pas complet, tente /admin/me pour fiabiliser
      if (!adminPayload?.email) {
        await fetchMe();
        return;
      }

      setAdmin(adminPayload);
      setStatus("authenticated");
    } catch {
      clearStorages();
      setAuthHeader(null);
      setAdmin(null);
      setStatus("unauthenticated");
    }
  };

  const logout = () => {
    clearStorages();
    setAuthHeader(null);
    setAdmin(null);
    setStatus("unauthenticated");
  };

  const value = useMemo(
    () => ({ status, admin, setStatus, setAdmin, login, logout }),
    [status, admin]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export default AuthProvider;
